        internal static bool TryGetCoordinateReference(int srid, out EpsgCoordinateReferenceRecord reference, out int cacheIndex)
        {
            switch (srid / 1000)
            {
                case 2:
                    return TryGetCoordinateReferenceBucket2(srid, out reference, out cacheIndex);
                case 3:
                    return TryGetCoordinateReferenceBucket3(srid, out reference, out cacheIndex);
                case 4:
