                case 20:
                    return TryGetCoordinateReferenceBucket20(srid, out reference, out cacheIndex);
                case 21:
                    return TryGetCoordinateReferenceBucket21(srid, out reference, out cacheIndex);
                case 22:
                    return TryGetCoordinateReferenceBucket22(srid, out reference, out cacheIndex);
                case 23:
                    return TryGetCoordinateReferenceBucket23(srid, out reference, out cacheIndex);
                case 24:
