                case 28:
                    return TryGetCoordinateReferenceBucket28(srid, out reference, out cacheIndex);
                case 29:
                    return TryGetCoordinateReferenceBucket29(srid, out reference, out cacheIndex);
                case 30:
                    return TryGetCoordinateReferenceBucket30(srid, out reference, out cacheIndex);
                case 31:
                    return TryGetCoordinateReferenceBucket31(srid, out reference, out cacheIndex);
                case 32:
                    return TryGetCoordinateReferenceBucket32(srid, out reference, out cacheIndex);
                default:
                    cacheIndex = -1;
                    reference = default;
                    return false;
            }
        }

